mainContent:
/**
 * Main Entry Point
 *
 * Vanilla JS BlockNote CRDT Demo
 * Initializes Velt client, user, document, and renders the UI.
 */

// Import styles
import '../styles/globals.css';
import './components/velt/ui-customization/styles.css';

// Import modules
import { initializeUser } from './lib/user.js';
import { initializeDocument } from './lib/document.js';
import { initializeTheme } from './lib/theme.js';
import {
  initializeVelt,
  authenticateUser,
  setVeltDocument,
  enableDarkMode,
} from './lib/velt.js';
import { createDocumentCanvas } from './components/document/document-canvas.js';
import { configureNotificationsTool } from './components/velt/velt-tools.js';
import { createBlockNoteEditor } from './components/document/blocknote/blocknote.js';
import { createVeltCollaboration } from './components/velt/velt-collaboration.js';

// App state
let documentCanvas = null;
let editorInstance = null;

/**
 * Wait for Velt to be fully initialized (user + document synced)
 * This ensures the awareness system knows the user info for cursor labels
 * @param {Object} veltClient - Velt client instance
 * @param {number} timeout - Timeout in milliseconds (default 30s)
 * @returns {Promise<boolean>}
 */
function waitForVeltInitState(veltClient, timeout = 30000) {
  return new Promise((resolve, reject) => {
    const startTime = Date.now();

    const subscription = veltClient.getVeltInitState().subscribe((state) => {
      console.log('[App] Velt init state:', state);

      if (state === true) {
        subscription?.unsubscribe();
        resolve(true);
        return;
      }

      // Check for timeout
      if (Date.now() - startTime > timeout) {
        subscription?.unsubscribe();
        console.warn('[App] Velt init state timeout, proceeding anyway');
        resolve(false);
      }
    });

    // Fallback timeout
    setTimeout(() => {
      subscription?.unsubscribe();
      console.warn('[App] Velt init state timeout (fallback), proceeding anyway');
      resolve(false);
    }, timeout);
  });
}

/**
 * Initialize the application
 */
async function init() {
  console.log('[App] Starting initialization...');

  const app = document.getElementById('app');
  if (!app) {
    console.error('[App] No #app element found');
    return;
  }

  // Show loading state
  app.innerHTML = `
    <div class="flex items-center justify-center h-screen w-screen" style="background-color: var(--app-bg);">
      <div style="color: var(--app-text-primary);" class="text-center">
        <div class="mb-4">
          <div class="animate-spin rounded-full h-8 w-8 border-b-2 border-current mx-auto"></div>
        </div>
        <p>Initializing collaboration...</p>
      </div>
    </div>
  `;

  try {
    // Step 1: Initialize user
    console.log('[App] Step 1: Initializing user...');
    const user = initializeUser();
    if (!user) {
      throw new Error('Failed to initialize user');
    }
    console.log('[App] User initialized:', user.name);

    // Step 2: Initialize document
    console.log('[App] Step 2: Initializing document...');
    const doc = initializeDocument();
    if (!doc.documentId) {
      throw new Error('Failed to initialize document');
    }
    console.log('[App] Document initialized:', doc.documentId);

    // Step 3: Initialize Velt client
    console.log('[App] Step 3: Initializing Velt client...');
    const veltClient = await initializeVelt();
    if (!veltClient) {
      throw new Error('Failed to initialize Velt client');
    }

    // Step 4: Authenticate user with Velt
    console.log('[App] Step 4: Authenticating user with Velt...');
    await authenticateUser(user);

    // Step 5: Set document in Velt
    console.log('[App] Step 5: Setting document in Velt...');
    await setVeltDocument(doc.documentId, doc.documentName);

    // Step 6: Initialize theme system (reads URL/localStorage, sets up listeners)
    console.log('[App] Step 6: Initializing theme...');
    initializeTheme();

    // Step 7: Configure notifications
    console.log('[App] Step 7: Configuring notifications...');
    configureNotificationsTool(veltClient);

    // Clear loading state
    app.innerHTML = '';

    // Step 8: Create main layout
    console.log('[App] Step 8: Creating main layout...');
    const mainContainer = document.createElement('main');
    mainContainer.className = 'w-full h-screen relative';
    app.appendChild(mainContainer);

    // Create document canvas
    documentCanvas = createDocumentCanvas(mainContainer);

    // Step 9: Wait for Velt init state before creating editor
    console.log('[App] Step 9: Waiting for Velt init state...');

    const editorContainer = documentCanvas.editorContainer;

    // Wait for Velt to be fully initialized (user + document synced)
    // This is critical - the editor must be created AFTER Velt knows who the user is
    await waitForVeltInitState(veltClient);
    console.log('[App] Velt fully initialized, creating editor...');

    if (editorContainer) {
      // Create editor with CRDT - now Velt knows the user info for cursor labels
      editorInstance = await createBlockNoteEditor(
        editorContainer,
        veltClient,
        doc.documentId
      );
      console.log('[App] Editor created successfully');
    }

    // Add Velt collaboration components (comments, sidebar)
    createVeltCollaboration(app);

    console.log('[App] Initialization complete!');
  } catch (error) {
    console.error('[App] Initialization failed:', error);
    app.innerHTML = `
      <div class="flex items-center justify-center h-screen w-screen" style="background-color: var(--app-bg);">
        <div class="text-center" style="color: var(--app-text-tertiary);">
          <p class="text-xl mb-2" style="color: #ef4444;">Failed to initialize</p>
          <p class="opacity-70">${error.message}</p>
          <button
            onclick="window.location.reload()"
            class="mt-4 px-4 py-2 rounded"
            style="background-color: var(--app-toggle-active-bg); color: var(--app-text-primary);"
          >
            Retry
          </button>
        </div>
      </div>
    `;
  }
}

/**
 * Cleanup on page unload
 */
function cleanup() {
  if (editorInstance && editorInstance.destroy) {
    editorInstance.destroy();
  }
  if (documentCanvas && documentCanvas.destroy) {
    documentCanvas.destroy();
  }
}

// Register cleanup
window.addEventListener('beforeunload', cleanup);

// Start the app when DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}

veltContent:
/**
 * Velt Client Initialization Module
 *
 * Uses @veltdev/client for vanilla JavaScript initialization.
 */

import { initVelt } from '@veltdev/client';

// Velt API Key - Replace with your own from https://console.velt.dev
const VELT_API_KEY = '6xTcUFtlYAlCdh11zrKB';
const VELT_AUTH_TOKEN = 'bd4d5226050470b6c658054fcdf1092a';

let veltClient = null;
let veltInitialized = false;
const initListeners = [];

/**
 * Get Velt client instance
 * @returns {Object|null} - Velt client or null
 */
export function getVeltClient() {
  return veltClient;
}

/**
 * Check if Velt is initialized
 * @returns {boolean} - Initialization state
 */
export function isVeltInitialized() {
  return veltInitialized;
}

/**
 * Subscribe to Velt initialization
 * @param {Function} callback - Callback function
 * @returns {Function} - Unsubscribe function
 */
export function subscribeToVeltInit(callback) {
  initListeners.push(callback);
  // Call immediately if already initialized
  if (veltInitialized) {
    callback(veltClient);
  }
  return () => {
    const index = initListeners.indexOf(callback);
    if (index > -1) {
      initListeners.splice(index, 1);
    }
  };
}

/**
 * Notify all listeners of initialization
 */
function notifyInitListeners() {
  initListeners.forEach(callback => callback(veltClient));
}

/**
 * Generate JWT token from Velt API
 * @param {Object} user - User object with userId, organizationId, email
 * @returns {Promise<string>} - JWT token
 */
async function generateVeltToken(user) {
  const body = {
    data: {
      userId: user.userId,
      userProperties: {
        organizationId: user.organizationId,
        email: user.email || undefined,
      },
    },
  };

  const response = await fetch('https://api.velt.dev/v2/auth/token/get', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-velt-api-key': VELT_API_KEY,
      'x-velt-auth-token': VELT_AUTH_TOKEN,
    },
    body: JSON.stringify(body),
  });

  const json = await response.json();
  const token = json?.result?.data?.token;

  if (!response.ok || !token) {
    throw new Error(json?.error?.message || 'Failed to generate token');
  }

  return token;
}

/**
 * Initialize Velt client
 * @returns {Promise<Object>} - Velt client
 */
export async function initializeVelt() {
  if (veltClient) {
    return veltClient;
  }

  try {
    veltClient = await initVelt(VELT_API_KEY);
    console.log('[Velt] Client initialized');
    return veltClient;
  } catch (error) {
    console.error('[Velt] Failed to initialize client:', error);
    throw error;
  }
}

/**
 * Authenticate user with Velt
 * @param {Object} user - User object
 * @returns {Promise<void>}
 */
export async function authenticateUser(user) {
  if (!veltClient) {
    throw new Error('Velt client not initialized');
  }

  if (!user) {
    throw new Error('User is required');
  }

  try {
    // Generate JWT token for secure authentication
    const token = await generateVeltToken(user);

    // Identify user with token
    await veltClient.identify(user, {
      authToken: token,
    });

    console.log('[Velt] User authenticated:', user.name);
  } catch (error) {
    console.error('[Velt] Failed to authenticate user:', error);
    // Fallback to simple identify without token (for demo purposes)
    try {
      await veltClient.identify(user);
      console.log('[Velt] User authenticated (without token):', user.name);
    } catch (fallbackError) {
      console.error('[Velt] Fallback authentication failed:', fallbackError);
      throw fallbackError;
    }
  }
}

/**
 * Set document in Velt
 * @param {string} documentId - Document ID
 * @param {string} documentName - Document name
 * @returns {Promise<void>}
 */
export async function setVeltDocument(documentId, documentName = 'Untitled') {
  if (!veltClient) {
    throw new Error('Velt client not initialized');
  }

  try {
    await veltClient.setDocument(documentId, {
      documentName: documentName,
    });
    console.log('[Velt] Document set:', documentId);
  } catch (error) {
    console.error('[Velt] Failed to set document:', error);
    throw error;
  }
}

/**
 * Enable dark mode
 */
export function enableDarkMode() {
  if (veltClient) {
    veltClient.setDarkMode(true);
  }
}

/**
 * Set Velt dark mode
 * @param {boolean} isDark - Whether to enable dark mode
 */
export function setVeltDarkMode(isDark) {
  if (veltClient) {
    veltClient.setDarkMode(isDark);
  }
}

/**
 * Sign out user
 */
export async function signOutUser() {
  if (veltClient) {
    try {
      await veltClient.signOutUser();
      console.log('[Velt] User signed out');
    } catch (error) {
      console.error('[Velt] Failed to sign out user:', error);
    }
  }
}

/**
 * Mark Velt as fully initialized (user + document set)
 */
export function markVeltInitialized() {
  veltInitialized = true;
  notifyInitListeners();
}

/**
 * Subscribe to Velt init state
 * @param {Function} callback - Callback function receiving boolean
 * @returns {Function} - Unsubscribe function
 */
export function subscribeToVeltInitState(callback) {
  if (!veltClient) {
    callback(false);
    return () => {};
  }

  const subscription = veltClient.getVeltInitState().subscribe((state) => {
    callback(state === true);
  });

  return () => {
    subscription?.unsubscribe();
  };
}

userContent:
/**
 * User Management Module
 *
 * This user authentication logic is ONLY for demo purposes.
 * It generates random users and stores them in localStorage/sessionStorage to simulate
 * a multi-user collaboration environment for demonstration.
 *
 * IN YOUR REAL APPLICATION:
 * - Fetch the currently logged in user from YOUR existing authentication system
 * - Use your own user management (Auth0, Firebase Auth, custom backend, etc.)
 * - Simply pass your authenticated user object to Velt's identify() method
 */

const STORAGE_KEY = 'blocknote-demo-user';

// Avatar colors for user icons
const avatarColors = ['#FF6B6B', '#4ECDC4', '#45B7D1', '#FFA07A', '#98D8C8', '#F7DC6F', '#BB8FCE', '#85C1E2'];

// Name pools for random user generation
const firstNames = ['Alex', 'Sam', 'Jordan', 'Taylor', 'Casey', 'Morgan', 'Riley', 'Avery'];
const lastNames = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones', 'Garcia', 'Miller', 'Davis'];

/**
 * Simple hash function to convert string to a consistent number
 * @param {string} str - Input string
 * @param {number} arrayLength - Array length for modulo
 * @returns {number} - Index within array bounds
 */
function hashStringToIndex(str, arrayLength) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32-bit integer
  }
  return Math.abs(hash) % arrayLength;
}

/**
 * Generate a deterministic hash from a string (for userId generation)
 * @param {string} str - Input string
 * @returns {string} - Hash string
 */
function hashString(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32-bit integer
  }
  // Convert to base36 and pad to ensure consistent length
  return Math.abs(hash).toString(36).padStart(8, '0');
}

/**
 * Generate a random user with deterministic ID based on name
 * @returns {Object} - User object
 */
function generateRandomUser() {
  // Randomly select first and last name
  const firstName = firstNames[Math.floor(Math.random() * firstNames.length)];
  const lastName = lastNames[Math.floor(Math.random() * lastNames.length)];
  const fullName = `${firstName} ${lastName}`;

  // Generate deterministic userId from the full name
  // This ensures "Alex Smith" always gets the same ID
  const userId = `user-${hashString(fullName)}`;

  // Use deterministic color based on userId for consistent photoUrl
  const colorIndex = hashStringToIndex(userId, avatarColors.length);
  const avatarColor = avatarColors[colorIndex];

  return {
    userId: userId,
    name: fullName,
    email: `${firstName.toLowerCase()}.${lastName.toLowerCase()}@example.com`,
    organizationId: 'sample-apps-demo-org',
    photoUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(fullName)}&background=${avatarColor.substring(1)}&color=fff&size=128`,
  };
}

/**
 * Get storage based on iframe context
 * @returns {Storage} - localStorage or sessionStorage
 */
function getStorage() {
  try {
    // Detect if running in iframe (for master-sample-app dual view)
    const isInIframe = window.self !== window.top;
    // In iframe: use sessionStorage (each origin/port is isolated automatically)
    // Not in iframe: use localStorage (same user across tabs)
    return isInIframe ? sessionStorage : localStorage;
  } catch {
    return localStorage;
  }
}

/**
 * User state management
 */
let currentUser = undefined;
let isUserLoggedIn = undefined;
const userListeners = [];

/**
 * Get current user
 * @returns {Object|undefined} - Current user or undefined
 */
export function getUser() {
  return currentUser;
}

/**
 * Check if user is logged in
 * @returns {boolean|undefined} - Login state
 */
export function getIsUserLoggedIn() {
  return isUserLoggedIn;
}

/**
 * Subscribe to user changes
 * @param {Function} callback - Callback function
 * @returns {Function} - Unsubscribe function
 */
export function subscribeToUser(callback) {
  userListeners.push(callback);
  // Call immediately with current state
  callback(currentUser, isUserLoggedIn);
  return () => {
    const index = userListeners.indexOf(callback);
    if (index > -1) {
      userListeners.splice(index, 1);
    }
  };
}

/**
 * Notify all listeners of user changes
 */
function notifyListeners() {
  userListeners.forEach(callback => callback(currentUser, isUserLoggedIn));
}

/**
 * Initialize user from storage or generate new one
 * @returns {Object} - User object
 */
export function initializeUser() {
  try {
    const storage = getStorage();

    // Check storage for existing user
    const stored = storage.getItem(STORAGE_KEY);

    if (stored) {
      // Use existing user from storage
      currentUser = JSON.parse(stored);
    } else {
      // Generate NEW random user
      currentUser = generateRandomUser();
      storage.setItem(STORAGE_KEY, JSON.stringify(currentUser));
    }

    isUserLoggedIn = true;
    notifyListeners();
    return currentUser;
  } catch {
    return undefined;
  }
}

/**
 * Login with a specific user
 * @param {Object} user - User object
 */
export function login(user) {
  try {
    const storage = getStorage();
    currentUser = user;
    isUserLoggedIn = true;
    storage.setItem(STORAGE_KEY, JSON.stringify(user));
    notifyListeners();
  } catch {
    // Ignore storage errors
  }
}

/**
 * Logout current user
 */
export function logout() {
  try {
    const storage = getStorage();
    currentUser = undefined;
    isUserLoggedIn = false;
    storage.removeItem(STORAGE_KEY);
    notifyListeners();
  } catch {
    // Ignore storage errors
  }
}

documentContent:
/**
 * Document Management Module
 *
 * This documentId logic using URL parameters is ONLY for demo sharing purposes.
 * It allows users to share a link to a specific document in this demo app.
 *
 * IN YOUR REAL APPLICATION:
 * - Use your own document ID system (e.g., from your database, CMS, or file system)
 * - You do NOT need to use URLs as document IDs
 * - Simply pass your existing document identifier to Velt
 */

const STORAGE_KEY = 'blocknote-crdt-document-id';

let documentId = null;
let isInitialized = false;

/**
 * Get current document info
 * @returns {Object} - Document object with id and name
 */
export function getCurrentDocument() {
  return {
    documentId: documentId,
    documentName: 'My Document',
  };
}

/**
 * Initialize document from URL or storage
 * @returns {Object} - Document object
 */
export function initializeDocument() {
  // Prevent double initialization
  if (isInitialized) {
    return getCurrentDocument();
  }

  // 1. Check URL for documentId parameter first
  const urlParams = new URLSearchParams(window.location.search);
  let docId = urlParams.get('documentId');

  if (docId) {
    // Use document ID from URL (shareable link)
    documentId = docId;
    localStorage.setItem(STORAGE_KEY, docId);
  } else {
    // 2. Check localStorage for existing document
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored) {
      docId = stored;
    } else {
      // 3. Generate new document ID
      docId = `doc-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
      localStorage.setItem(STORAGE_KEY, docId);
    }

    // Update URL with document ID for shareability
    const newUrl = `${window.location.pathname}?documentId=${docId}`;
    window.history.pushState({}, '', newUrl);

    documentId = docId;
  }

  isInitialized = true;
  return getCurrentDocument();
}

/**
 * Get the document ID
 * @returns {string|null} - Document ID
 */
export function getDocumentId() {
  return documentId;
}

themeContent:
/**
 * Theme Management Module
 *
 * Vanilla JS port of the React ThemeContext.
 * Supports light, dark, and system themes with URL param override and postMessage sync.
 */

import { setVeltDarkMode } from './velt.js';

const STORAGE_KEY = 'theme-preference';

let currentTheme = 'dark';
let resolvedTheme = 'dark';
const themeListeners = [];

/**
 * Get system theme preference
 * @returns {'light'|'dark'} - System theme
 */
function getSystemTheme() {
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

/**
 * Resolve a theme value to light or dark
 * @param {'light'|'dark'|'system'} theme - Theme value
 * @returns {'light'|'dark'} - Resolved theme
 */
function resolveThemeValue(theme) {
  if (theme === 'system') return getSystemTheme();
  return theme;
}

/**
 * Apply theme to the DOM
 * @param {'light'|'dark'} resolved - Resolved theme
 */
function applyTheme(resolved) {
  if (resolved === 'dark') {
    document.documentElement.classList.add('dark');
  } else {
    document.documentElement.classList.remove('dark');
  }
  // Sync Velt dark mode
  setVeltDarkMode(resolved === 'dark');
}

/**
 * Read theme from URL ?theme= param
 * @returns {'light'|'dark'|'system'|null}
 */
function getUrlTheme() {
  const params = new URLSearchParams(window.location.search);
  const t = params.get('theme');
  if (t === 'light' || t === 'dark' || t === 'system') return t;
  return null;
}

/**
 * Get initial theme from URL or localStorage
 * @returns {'light'|'dark'|'system'}
 */
function getInitialTheme() {
  return getUrlTheme() || localStorage.getItem(STORAGE_KEY) || 'dark';
}

/**
 * Notify all theme listeners
 */
function notifyListeners() {
  themeListeners.forEach(callback => callback(resolvedTheme, currentTheme));
}

/**
 * Get current resolved theme
 * @returns {'light'|'dark'}
 */
export function getResolvedTheme() {
  return resolvedTheme;
}

/**
 * Get current theme setting
 * @returns {'light'|'dark'|'system'}
 */
export function getTheme() {
  return currentTheme;
}

/**
 * Set theme
 * @param {'light'|'dark'|'system'} theme - Theme to set
 */
export function setTheme(theme) {
  currentTheme = theme;
  localStorage.setItem(STORAGE_KEY, theme);
  resolvedTheme = resolveThemeValue(theme);
  applyTheme(resolvedTheme);
  notifyListeners();
}

/**
 * Subscribe to theme changes
 * @param {Function} callback - Callback receiving (resolvedTheme, theme)
 * @returns {Function} - Unsubscribe function
 */
export function subscribeToTheme(callback) {
  themeListeners.push(callback);
  // Call immediately with current state
  callback(resolvedTheme, currentTheme);
  return () => {
    const index = themeListeners.indexOf(callback);
    if (index > -1) {
      themeListeners.splice(index, 1);
    }
  };
}

/**
 * Initialize theme system
 * Sets up listeners for postMessage and system preference changes.
 */
export function initializeTheme() {
  // Set initial theme
  currentTheme = getInitialTheme();
  resolvedTheme = resolveThemeValue(currentTheme);
  applyTheme(resolvedTheme);

  // Listen for postMessage from master app for live theme switching
  window.addEventListener('message', (event) => {
    if (event.data?.type === 'theme-change' && event.data.theme) {
      setTheme(event.data.theme);
    }
  });

  // Listen for system preference changes when theme is 'system'
  const mq = window.matchMedia('(prefers-color-scheme: dark)');
  mq.addEventListener('change', () => {
    if (currentTheme === 'system') {
      resolvedTheme = getSystemTheme();
      applyTheme(resolvedTheme);
      notifyListeners();
    }
  });
}

documentCanvasContent:
/**
 * Document Canvas Component
 *
 * Vanilla JS port of the React DocumentCanvas component.
 * Main layout wrapper with Header, Sidebar, and Editor area.
 */

import { createHeader } from '../header/header.js';
import { createSidebar } from '../sidebar/sidebar.js';

/**
 * Create the document canvas layout
 * @param {HTMLElement} container - Container element to append to
 * @returns {Object} - Component API with editorContainer, el, and destroy methods
 */
export function createDocumentCanvas(container) {
  // Root: flex column, full size
  const root = document.createElement('div');
  root.className = 'flex flex-col w-full h-full';

  // Header
  const headerInstance = createHeader(root);

  // Content area: flex row
  const content = document.createElement('div');
  content.className = 'flex flex-1 overflow-hidden';

  // Sidebar
  const sidebarInstance = createSidebar(content);

  // Editor wrapper
  const editorWrapper = document.createElement('div');
  editorWrapper.className = 'flex-1 overflow-hidden';

  const editorContainer = document.createElement('div');
  editorContainer.className = 'w-full h-full relative';
  editorWrapper.appendChild(editorContainer);

  content.appendChild(editorWrapper);
  root.appendChild(content);
  container.appendChild(root);

  return {
    el: root,
    editorContainer,
    destroy() {
      if (headerInstance && headerInstance.destroy) headerInstance.destroy();
      if (sidebarInstance && sidebarInstance.destroy) sidebarInstance.destroy();
      root.remove();
    },
  };
}

blocknoteContent:
/**
 * BlockNote Editor Component with Velt CRDT
 *
 * Vanilla JS implementation using createCollaboration from @veltdev/blocknote-crdt (v2 API)
 * for real-time collaborative block editing.
 */

import { BlockNoteEditor } from '@blocknote/core';
import '@blocknote/core/fonts/inter.css';
import '@blocknote/mantine/style.css';
import { createCollaboration } from '@veltdev/blocknote-crdt';
import { blockNoteInitialContent } from './constants.js';
import { getResolvedTheme, subscribeToTheme } from '../../../lib/theme.js';

/**
 * Create loading spinner element
 * @returns {HTMLElement}
 */
function createLoadingSpinner() {
  const spinner = document.createElement('div');
  spinner.className = 'flex items-center justify-center h-full';
  spinner.style.color = 'var(--app-text-tertiary)';
  spinner.innerHTML = `
    <div class="text-center">
      <div class="mb-4">
        <div class="animate-spin rounded-full h-8 w-8 border-b-2 border-current mx-auto"></div>
      </div>
      <p>Loading editor...</p>
    </div>
  `;
  return spinner;
}

/**
 * Create status indicator element
 * @returns {Object} - { el, update }
 */
function createStatusIndicator() {
  const wrapper = document.createElement('div');
  wrapper.className = 'flex items-center gap-1.5 px-4 pt-2';

  const dot = document.createElement('span');
  dot.className = 'inline-block rounded-full shrink-0';
  Object.assign(dot.style, { width: '8px', height: '8px', backgroundColor: '#eab308' });

  const label = document.createElement('span');
  label.className = 'text-xs';
  label.style.color = 'var(--app-text-tertiary)';
  label.textContent = 'Connecting\u2026';

  wrapper.appendChild(dot);
  wrapper.appendChild(label);

  return {
    el: wrapper,
    update(status, synced) {
      if (status === 'connected') {
        dot.style.backgroundColor = synced ? '#22c55e' : '#eab308';
        label.textContent = synced ? 'Synced' : 'Syncing\u2026';
      } else if (status === 'connecting') {
        dot.style.backgroundColor = '#eab308';
        label.textContent = 'Connecting\u2026';
      } else {
        dot.style.backgroundColor = '#ef4444';
        label.textContent = 'Disconnected';
      }
    },
  };
}

/**
 * Create BlockNote editor with Velt CRDT
 * @param {HTMLElement} container - Container element to mount into
 * @param {Object} veltClient - Velt client instance
 * @param {string} editorId - Unique editor ID
 * @returns {Promise<Object>} - Component API with editor, manager, and destroy methods
 */
export async function createBlockNoteEditor(container, veltClient, editorId) {
  // Create editor container structure
  const editorContainerEl = document.createElement('div');
  editorContainerEl.className = 'editor-container';

  // Show loading state
  const loadingSpinner = createLoadingSpinner();
  const editorContent = document.createElement('div');
  editorContent.className = 'editor-content';
  editorContent.appendChild(loadingSpinner);
  editorContainerEl.appendChild(editorContent);
  container.appendChild(editorContainerEl);

  let editor = null;
  let manager = null;
  let statusIndicator = null;
  let themeUnsubscribe = null;

  try {
    // [Velt] Create the CollaborationManager using createCollaboration (v2 API)
    console.log('[BlockNote] Creating collaboration manager...');
    manager = await createCollaboration({
      editorId: editorId,
      veltClient: veltClient,
      onError: (error) => console.error('[BlockNote] Collaboration error:', error),
    });

    console.log('[BlockNote] Collaboration manager created, initializing editor...');

    // Get collaboration config for BlockNote
    const collabConfig = manager.getCollaborationConfig();

    // Create BlockNote editor with collaboration
    editor = BlockNoteEditor.create({
      collaboration: collabConfig,
    });

    // Remove loading spinner and rebuild layout
    editorContent.removeChild(loadingSpinner);

    // Add status indicator before editor content
    statusIndicator = createStatusIndicator();
    editorContainerEl.insertBefore(statusIndicator.el, editorContent);

    // Create mount point for BlockNote
    const mountPoint = document.createElement('div');
    mountPoint.className = 'w-full h-full';
    editorContent.appendChild(mountPoint);

    // Mount editor to DOM
    editor.mount(mountPoint);

    // Apply initial content if document is empty (brand-new document)
    const blocks = editor.document;
    const isEmpty =
      blocks.length === 0 ||
      (blocks.length === 1 &&
        blocks[0].type === 'paragraph' &&
        Array.isArray(blocks[0].content) &&
        blocks[0].content.length === 0);
    if (isEmpty) {
      console.log('[BlockNote] Document is empty, applying initial content...');
      editor.replaceBlocks(editor.document, blockNoteInitialContent);
    }

    // [Velt] Subscribe to status and sync events (v2 API)
    statusIndicator.update(manager.status, manager.synced);

    manager.onStatusChange((status) => {
      console.log('[BlockNote] Connection status:', status);
      statusIndicator.update(status, manager.synced);
    });

    manager.onSynced((synced) => {
      console.log('[BlockNote] Synced:', synced);
      statusIndicator.update(manager.status, synced);
    });

    // Theme: BlockNote dark mode is handled via CSS (.dark .bn-editor selectors in globals.css)
    // We also set the data-color-scheme attribute on the BlockNote container
    themeUnsubscribe = subscribeToTheme((resolved) => {
      const bnContainer = mountPoint.querySelector('.bn-container');
      if (bnContainer) {
        bnContainer.setAttribute('data-color-scheme', resolved);
      }
    });

    console.log('[BlockNote] Editor initialized successfully');

  } catch (error) {
    console.error('[BlockNote] Failed to initialize:', error);

    // Show error state
    editorContainerEl.innerHTML = '';
    statusIndicator = createStatusIndicator();
    statusIndicator.update('disconnected', false);
    editorContainerEl.appendChild(statusIndicator.el);

    // Update status to show error
    const dot = statusIndicator.el.querySelector('span');
    if (dot) dot.style.backgroundColor = '#ef4444';
    const label = statusIndicator.el.querySelectorAll('span')[1];
    if (label) {
      label.style.color = '#ef4444';
      label.textContent = `Failed to initialize: ${error.message}`;
    }
  }

  return {
    editor,
    manager,
    destroy() {
      if (themeUnsubscribe) {
        themeUnsubscribe();
        themeUnsubscribe = null;
      }
      if (editor) {
        editor.mount(null);
        editor = null;
      }
      if (manager) {
        manager.destroy();
        manager = null;
      }
      editorContainerEl.remove();
    },
  };
}

