/* Dark theme overrides for BlockNote */
.dark .bn-editor,
[data-color-scheme="dark"] .bn-editor {
  --bn-colors-editor-background: #000000 !important;
  --bn-colors-editor-text: #ffffff !important;
}

.dark .bn-container[data-color-scheme="dark"],
.dark .bn-container {
  --bn-colors-editor-background: #000000 !important;
  --bn-colors-editor-text: #ffffff !important;
}

/* Paragraph opacity in body text (matching tiptap) */
.bn-editor .bn-block-content[data-content-type="paragraph"] .bn-inline-content {
  opacity: 0.8;
}

.bn-editor .bn-block-content[data-content-type="heading"] .bn-inline-content {
  opacity: 1;
}

/* Collaboration cursor styling */
.collaboration-cursor__caret, .collaboration-carets__caret {
  border-left: 1px solid #ffffff;
  border-right: 1px solid #ffffff;
  margin-left: -1px;
  margin-right: -1px;
  pointer-events: none;
  position: relative;
  word-break: normal;
}

.collaboration-cursor__label, .collaboration-carets__label {
  border-radius: 3px 3px 3px 0;
  color: #0d0d0d;
  font-size: 12px;
  font-style: normal;
  font-weight: 600;
  left: -1px;
  line-height: normal;
  padding: 0.1rem 0.3rem;
  position: absolute;
  top: -1.4em;
  user-select: none;
  white-space: nowrap;
}
